// tenantUserFieldStrings are the columns fields selects, in OrderedMembers
// order so FK columns match scan order, and the primary key when fields
// hydrates a hasMany relation, which maps the children by it.
func tenantUserFieldStrings(fields TenantUserFields) []string {
	var fieldStrings []string
	if fields.CreatedAt {
		fieldStrings = append(fieldStrings, "created_at")
	}
	if fields.UpdatedAt {
		fieldStrings = append(fieldStrings, "updated_at")
	}
	if fields.Id {
		fieldStrings = append(fieldStrings, "id")
	}
	if fields.Tenant || !fields.TenantNested.IsZero() {
		fieldStrings = append(fieldStrings, "tenant_id")
	}
	if fields.DisplayName {
		fieldStrings = append(fieldStrings, "display_name")
	}
	if fields.DeletedAt {
		fieldStrings = append(fieldStrings, "deleted_at")
	}
	if fields.DeletedBy {
		fieldStrings = append(fieldStrings, "deleted_by")
	}
	if fields.Version {
		fieldStrings = append(fieldStrings, "_version")
	}
	return fieldStrings
}

// findRows runs query, a select of the columns fieldStrings names, in turn,
// with args, scans its rows, and hydrates the relations fields selects, as
// FindMany and FindPage read them. method names the caller in an error.
func (r *TenantUserRepository) findRows(ctx context.Context, method, query string, args []interface{}, fieldStrings []string, fields TenantUserFields) ([]*types.TenantUser, error) {
	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results
	results := []*types.TenantUser{}
	for rows.Next() {
		result := &types.TenantUser{}

		// Create temporary variables for nullable fields that need pointer scanning (per-row)

		var tempDisplayName sql.NullString

		// Create temporary variables for relationship foreign keys (we don't store these directly on the struct)
		var tempRelTenant *types.IdentityUUID

		// Track whether special fields were selected so we can post-process after Scan.

		var selectedDisplayName bool
		var selectedRelTenant bool

		scanDest := make([]any, len(fieldStrings))
		for i, fieldName := range fieldStrings {
			switch fieldName {
			case "created_at":
				scanDest[i] = &result.CreatedAt
			case "updated_at":
				scanDest[i] = &result.UpdatedAt
			case "id":
				scanDest[i] = &result.Id
			case "display_name":
				scanDest[i] = &tempDisplayName
				selectedDisplayName = true
			case "deleted_at":
				scanDest[i] = &result.DeletedAt
			case "deleted_by":
				scanDest[i] = &result.DeletedBy
			case "_version":
				scanDest[i] = &result.Version
			case "tenant_id":
				scanDest[i] = &tempRelTenant
				selectedRelTenant = true
			default:
				return nil, fmt.Errorf("unexpected field %q for TenantUser.%s", fieldName, method)
			}
		}

		if err := rows.Scan(scanDest...); err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present
		var jsonFieldDecodeErr error

		if selectedDisplayName && tempDisplayName.Valid {
			result.DisplayName = tempDisplayName.String
		}
		if jsonFieldDecodeErr != nil {
			return nil, jsonFieldDecodeErr
		}

		// Set relationship IDs from scanned FK values (hydration happens after loop)
		if selectedRelTenant && tempRelTenant != nil {
			result.Tenant.Id = tenantUserUUIDPtr(*tempRelTenant)
		}

		results = append(results, result)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	// Batch hydrate relationships (outside the row loop for efficiency)
	if fields.Tenant || !fields.TenantNested.IsZero() {
		// Collect unique FK IDs from results (dedupe during collection)
		tenantIDSet := make(map[types.IdentityUUID]bool)
		var tenantIDs []types.IdentityUUID
		for _, result := range results {
			var zeroID types.IdentityUUID
			tenantID, ok := tenantUserUUIDValue(result.Tenant.Id)
			if ok && tenantID != zeroID && !tenantIDSet[tenantID] {
				tenantIDSet[tenantID] = true
				tenantIDs = append(tenantIDs, tenantID)
			}
		}

		// Batch fetch related entities with typed child field options.
		childFields := (TenantFields{}).All()
		childFieldsAreDefault := true
		if !fields.TenantNested.IsZero() {
			childFields = fields.TenantNested
			childFieldsAreDefault = false
		}

		tenantMap, err := r.batchTenantByIDs(ctx, tenantIDs, &TenantFindOptions{
			Fields: childFields,
			Limit:  len(tenantIDs),
		}, childFieldsAreDefault)
		if err != nil {
			return nil, fmt.Errorf("failed to batch fetch tenant: %w", err)
		}

		// Hydrate results from map
		for _, result := range results {
			tenantID, ok := tenantUserUUIDValue(result.Tenant.Id)
			if ok {
				if rel, ok := tenantMap[tenantID]; ok {
					result.Tenant = *rel
				}
			}
		}
	}

	return results, nil
}

// FindPage reads a page of the TenantUser rows filter finds (D60, amended), in
// opts.Sort's order, ties broken by id in the same direction: up to
// opts.Limit rows after opts.After, and Next when more follow. It runs one
// query of opts.Limit + 1 rows and no count. A key is a row's id alone:
// in an order by a sort field, the query reads the key's row for its value,
// soft-deleted or not and whatever the filter, so a row the filter no longer
// finds still places the page. An After that holds no id, or whose row
// no longer exists in an order by a sort field, is ErrPageKey. A key of another
// order cannot be told from one of this order: the router refuses a cursor
// of another sort before FindPage reads it.
func (r *TenantUserRepository) FindPage(ctx context.Context, filter *TenantUserFilter, opts *TenantUserPageOptions) (*TenantUserPage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of TenantUser rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = TenantUserSortById
	}
	column, ok := tenantUserSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: TenantUser sorts by id and createdAt, not %q", string(field))
	}
	byKey := field == TenantUserSortById

	// Next is the key of the page's last row, so the page reads its primary
	// key whatever Fields selects.
	fieldStrings := tenantUserFieldStrings(opts.Fields)
	if !containsString(fieldStrings, "id") {
		fieldStrings = append(fieldStrings, "id")
	}
	if err := validateFields(fieldStrings, TenantUserAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "tenant_user")
	// The filter's conditions, each qualified by the table, then the
	// soft-delete condition, then the keyset's.
	var args []interface{}
	conditions := filter.conditions(&args, 0)
	if !opts.IncludeDeleted {
		conditions = append(conditions, `tenant_user.deleted_at IS NULL`)
	}
	comparison, direction := ">", "ASC"
	if opts.Sort.Desc {
		comparison, direction = "<", "DESC"
	}
	var key any
	if opts.After != nil {
		var err error
		if key, err = opts.After.arg(); err != nil {
			return nil, err
		}
		args = append(args, key)
		placeholder := fmt.Sprintf("$%d", len(args))
		if byKey {
			conditions = append(conditions, fmt.Sprintf(`tenant_user.id %s %s`, comparison, placeholder))
		} else {
			// The key's row gives the sort field's value: no deleted_at
			// condition and no filter, so a row soft-deleted or changed
			// since the page before still places this one.
			conditions = append(conditions, fmt.Sprintf(`(%s, tenant_user.id) %s ((SELECT %s FROM tenant_user AS page_key WHERE page_key.id = %s), %s)`,
				column.sql, comparison, column.key, placeholder, placeholder))
		}
	}
	whereClause := ""
	if len(conditions) > 0 {
		whereClause = " WHERE " + strings.Join(conditions, " AND ")
	}
	orderByClause := fmt.Sprintf(" ORDER BY %s %s", column.sql, direction)
	if !byKey {
		orderByClause += fmt.Sprintf(`, tenant_user.id %s`, direction)
	}
	query := fmt.Sprintf(`SELECT %s FROM tenant_user%s%s LIMIT %d`, selectFields, whereClause, orderByClause, limit+1)

	rows, err := r.findRows(ctx, "FindPage", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 && opts.After != nil && !byKey {
		// A key whose row no longer exists places no row: its value is
		// null, which no row comes after. Only then is the page empty
		// without being the last.
		if err := r.pageKeyExists(ctx, key); err != nil {
			return nil, err
		}
	}
	page := &TenantUserPage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = tenantUserPageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// pageKeyExists is nil when the table holds a row whose primary key is key,
// soft-deleted or not, and ErrPageKey when it holds none.
func (r *TenantUserRepository) pageKeyExists(ctx context.Context, key any) error {
	query := `SELECT EXISTS (SELECT 1 FROM tenant_user WHERE tenant_user.id = $1)`
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, key)
	} else {
		row = r.db.pool.QueryRow(ctx, query, key)
	}
	var exists bool
	if err := row.Scan(&exists); err != nil {
		return fmt.Errorf("failed to read the page key's row: %w", err)
	}
	if !exists {
		return fmt.Errorf("%w: no TenantUser row has the key's id", ErrPageKey)
	}
	return nil
}

// CreateOne inserts a new TenantUser record
func (r *TenantUserRepository) CreateOne(ctx context.Context, input *types.TenantUser) (*types.TenantUser, error) {
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := tenantUserUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Optional field: displayName - only add if set
	{
		if !reflect.ValueOf(input.DisplayName).IsZero() {
			fields = append(fields, `display_name`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.DisplayName)
		}
	}
	// Optional field: deletedAt - only add if set
	{
		if input.DeletedAt != nil {
			fields = append(fields, `deleted_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.DeletedAt))
		}
	}
	// Optional field: deletedBy - only add if set
	{
		if input.DeletedBy != nil {
			fields = append(fields, `deleted_by`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.DeletedBy.ToUUID())
		}
	}

	// Handle relationship foreign key columns
	// Relationship: tenant (FK: tenant_id)
	{
		var zeroId types.IdentityUUID
		if relID, ok := tenantUserUUIDValue(input.Tenant.Id); ok && relID != zeroId {
			fields = append(fields, `tenant_id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, relID.ToUUID())
		}
	}

	// Build RETURNING clause with explicit column order matching scan order (using OrderedMembers for schema order)
	returningClause := `"created_at", "updated_at", "id", "tenant_id", "display_name", "deleted_at", "deleted_by", "_version"`
	query := fmt.Sprintf(
		`INSERT INTO tenant_user (%s) VALUES (%s) RETURNING %s`,
		strings.Join(fields, ", "),
		strings.Join(placeholders, ", "),
		returningClause,
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}

	// Scan result
	result := &types.TenantUser{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempDisplayName sql.NullString

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)
	var tempRelTenant *types.IdentityUUID

	// Scan all fields in schema order (matches DDL column order)
	if err := row.Scan(

		&result.CreatedAt,

		&result.UpdatedAt,

		&result.Id,

		&tempRelTenant,

		&tempDisplayName,

		&result.DeletedAt,

		&result.DeletedBy,

		&result.Version,
	); err != nil {
		return nil, fmt.Errorf("failed to scan result: %w", err)
	}

	// Copy nullable fields when present

	if tempDisplayName.Valid {
		result.DisplayName = tempDisplayName.String
	}

	// Set relationship IDs from scanned FK values
	if tempRelTenant != nil {
		result.Tenant.Id = tenantUserUUIDPtr(*tempRelTenant)
	}

	return result, nil
}

// tenantUserUniqueKeys are the conflict targets of TenantUser's unique keys, and
// the assignment an upsert that sets nothing writes, so the row it
// conflicts with is returned (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert only if changed reads back, empty for a
// key over an expression, and the key's columns as a batch insert's cells
// name them (D89).
var tenantUserUniqueKeys = map[TenantUserUniqueKey]struct {
	conflict, keep, rows string
	columns              []string
}{
	TenantUserUniqueById:                {`(id)`, `id = EXCLUDED.id`, `SELECT "created_at", "updated_at", "id", "tenant_id", "display_name", "deleted_at", "deleted_by", "_version" FROM tenant_user WHERE (id) IN (%s)`, []string{`id`}},
	TenantUserUniqueByTenantDisplayName: {`(tenant_id, display_name) WHERE deleted_at IS NULL`, `tenant_id = EXCLUDED.tenant_id`, `SELECT "created_at", "updated_at", "id", "tenant_id", "display_name", "deleted_at", "deleted_by", "_version" FROM tenant_user WHERE (tenant_id, display_name) IN (%s) AND (deleted_at IS NULL)`, []string{`tenant_id`, `display_name`}},
}

// tenantUserKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func tenantUserKeyOf(on TenantUserUniqueKey, row *types.TenantUser) (string, bool) {
	switch on {
	case TenantUserUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	case TenantUserUniqueByTenantDisplayName:
		return upsertKeyText(upsertKeyValue(row.Tenant.Id, false), upsertKeyValue(row.DisplayName, true))
	}
	return "", false
}

// database is the Database the repository runs on.
func (r *TenantUserRepository) database() *Database {
	if r.txDB != nil {
		return r.txDB
	}
	return r.db
}

// scanReturned scans a row of every column of TenantUser, as a write returns
// it, and, with inserted, the flag an upsert returns after them (D89).
func (r *TenantUserRepository) scanReturned(row pgx.Row, inserted *bool) (*types.TenantUser, error) {
	result := &types.TenantUser{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempDisplayName sql.NullString

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)
	var tempRelTenant *types.IdentityUUID

	// Scan all fields in schema order (matches DDL column order)
	dest := []any{

		&result.CreatedAt,

		&result.UpdatedAt,

		&result.Id,

		&tempRelTenant,

		&tempDisplayName,

		&result.DeletedAt,

		&result.DeletedBy,

		&result.Version,
	}
	if inserted != nil {
		dest = append(dest, inserted)
	}
	if err := row.Scan(dest...); err != nil {
		return nil, err
	}

	// Copy nullable fields when present

	if tempDisplayName.Valid {
		result.DisplayName = tempDisplayName.String
	}

	// Set relationship IDs from scanned FK values
	if tempRelTenant != nil {
		result.Tenant.Id = tenantUserUUIDPtr(*tempRelTenant)
	}

	return result, nil
}

// UpsertOne inserts input, or, when a row already holds its value of the
// unique key on, applies update to that row instead, and returns the row
// (D79). The insert writes what CreateOne writes and the update what
// UpdateOne writes, updated_at and updated_by among it, but an update that
// sets no field leaves the row as it is. A soft-deleted row that holds the key is
// left as it is, and UpsertOne returns ErrNotFound.
func (r *TenantUserRepository) UpsertOne(ctx context.Context, input *types.TenantUser, on TenantUserUniqueKey, update *TenantUserUpdate) (*types.TenantUser, error) {
	result, err := r.UpsertOneResult(ctx, input, on, update, nil)
	if err != nil {
		return nil, err
	}
	return result.Row, nil
}

// UpsertOneResult is UpsertOne, and what it did with the row: inserted it,
// updated the row that held the key, or left that row as it was (D89).
// With opts.OnlyIfChanged it updates the row only when a field the update
// sets differs from what the row holds, which it reads back otherwise. A write that
// may take more than one statement runs in a transaction of its own when
// none is open.
func (r *TenantUserRepository) UpsertOneResult(ctx context.Context, input *types.TenantUser, on TenantUserUniqueKey, update *TenantUserUpdate, opts *UpsertOptions) (UpsertResult[*types.TenantUser], error) {
	var none UpsertResult[*types.TenantUser]
	key, ok := tenantUserUniqueKeys[on]
	if !ok {
		return none, fmt.Errorf("orm: TenantUser has no unique key %q", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if opts.OnlyIfChanged && key.rows == "" {
		return none, upsertExpressionKey("UpsertOneResult", "TenantUser", string(on))
	}
	if update == nil {
		update = &TenantUserUpdate{}
	}
	write := func(repo *TenantUserRepository) (UpsertResult[*types.TenantUser], error) {
		result, err := repo.upsertRow(ctx, input, on, update, opts.OnlyIfChanged)
		if err != nil {
			return none, err
		}
		return *result, nil
	}
	if !opts.OnlyIfChanged {
		return write(r)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (UpsertResult[*types.TenantUser], error) {
		return write(&TenantUserRepository{tx: tx, txDB: r.database()})
	})
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, only if changed, and the second
// statement of an encrypted field.
func (r *TenantUserRepository) upsertRow(ctx context.Context, input *types.TenantUser, on TenantUserUniqueKey, update *TenantUserUpdate, onlyIfChanged bool) (*UpsertResult[*types.TenantUser], error) {
	key := tenantUserUniqueKeys[on]
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := tenantUserUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Optional field: displayName - only add if set
	{
		if !reflect.ValueOf(input.DisplayName).IsZero() {
			fields = append(fields, `display_name`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.DisplayName)
		}
	}
	// Optional field: deletedAt - only add if set
	{
		if input.DeletedAt != nil {
			fields = append(fields, `deleted_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.DeletedAt))
		}
	}
	// Optional field: deletedBy - only add if set
	{
		if input.DeletedBy != nil {
			fields = append(fields, `deleted_by`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.DeletedBy.ToUUID())
		}
	}

	// Handle relationship foreign key columns
	// Relationship: tenant (FK: tenant_id)
	{
		var zeroId types.IdentityUUID
		if relID, ok := tenantUserUUIDValue(input.Tenant.Id); ok && relID != zeroId {
			fields = append(fields, `tenant_id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, relID.ToUUID())
		}
	}

	// Build the update of the row the key conflicts with, its placeholders
	// numbered after the insert's
	var setClauses, compareCurrent, compareNext []string
	if update.DisplayName != nil && update.DisplayNameSetNull {
		return nil, fmt.Errorf("display_name cannot be updated with both value and null assignment")
	}
	if update.DisplayNameSetNull {
		setClauses = append(setClauses, `display_name = NULL`)
		compareCurrent = append(compareCurrent, `tenant_user.display_name`)
		compareNext = append(compareNext, `NULL`)
	} else if update.DisplayName != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`display_name = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `tenant_user.display_name`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.DisplayName)
	}
	// Handle relationship foreign key: tenant
	if update.TenantID != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf("tenant_id = $%d", paramNum))
		compareCurrent = append(compareCurrent, `tenant_user.tenant_id`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, update.TenantID.ToUUID())
	}

	assigned := len(setClauses)
	if assigned == 0 {
		// An update that sets no field leaves the row as it is, stamps and
		// all, and returns it.
		setClauses = append(setClauses, key.keep)
	} else {
		// Set updated_at
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf("updated_at = $%d", paramNum))
		values = append(values, time.Now())

		// Set updated_by

	}

	query := fmt.Sprintf(
		`INSERT INTO tenant_user (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "created_at", "updated_at", "id", "tenant_id", "display_name", "deleted_at", "deleted_by", "_version", (xmax = 0) AS _inserted`,
		strings.Join(fields, ", "),
		"("+strings.Join(placeholders, ", ")+")",
		key.conflict,
		strings.Join(setClauses, ", "),
		upsertWhere(`tenant_user.deleted_at IS NULL`, compareCurrent, compareNext, onlyIfChanged),
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}
	var inserted bool
	scanned, err := r.scanReturned(row, &inserted)
	var upserted *UpsertResult[*types.TenantUser]
	switch {
	case err == nil:
		status := UpsertUnchanged
		if inserted {
			status = UpsertInserted
		} else if assigned > 0 {
			status = UpsertUpdated
		}
		upserted = &UpsertResult[*types.TenantUser]{Row: scanned, Status: status}
	case err != pgx.ErrNoRows:
		return nil, fmt.Errorf("failed to scan result: %w", err)
	case !onlyIfChanged:
		// The row the key conflicts with is soft-deleted.
		return nil, ErrNotFound
	default:
		// The row the key conflicts with already held the update's values.
		keyValues, ok := upsertCellValues(upsertCells(fields, values), key.columns)
		if !ok {
			return nil, fmt.Errorf("no TenantUser row holds an unset %s: %w", string(on), ErrNotFound)
		}
		found, err := r.rowsOfKeys(ctx, on, [][]any{keyValues}, []*types.TenantUser{input})
		if err != nil {
			return nil, err
		}
		upserted = &UpsertResult[*types.TenantUser]{Row: found[0], Status: UpsertUnchanged}
	}
	return upserted, nil
}

// UpsertMany inserts each input, or, when a row already holds its value of
// the unique key on, sets each field update names of that row to the value
// the input would have inserted, and returns each input's row and what it
// did with it, in the inputs' order (D89). One statement writes a batch of
// rows, opts.Batch or as many as Postgres binds the parameters of, and more
// rows take a statement per batch, in one transaction; a write that may
// take more than one statement runs in a transaction of its own when none
// is open. An update that names no field leaves each row that holds a key
// as it is. A soft-deleted row that holds a key is left as it is, and
// UpsertMany returns ErrNotFound. Two inputs of one batch that hold one key fail
// the statement, and a key over an expression, whose rows the statement's
// cannot be matched to the inputs by, is refused.
func (r *TenantUserRepository) UpsertMany(ctx context.Context, inputs []*types.TenantUser, on TenantUserUniqueKey, update TenantUserFields, opts *UpsertOptions) ([]UpsertResult[*types.TenantUser], error) {
	key, ok := tenantUserUniqueKeys[on]
	if !ok {
		return nil, fmt.Errorf("orm: TenantUser has no unique key %q", string(on))
	}
	if key.rows == "" {
		return nil, upsertExpressionKey("UpsertMany", "TenantUser", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if update.CreatedAt {
		return nil, fmt.Errorf("orm: UpsertMany of TenantUser sets the fields an update sets, not createdAt")
	}
	if update.UpdatedAt {
		return nil, fmt.Errorf("orm: UpsertMany of TenantUser sets the fields an update sets, not updatedAt")
	}
	if update.Id {
		return nil, fmt.Errorf("orm: UpsertMany of TenantUser sets the fields an update sets, not id")
	}
	if update.DeletedAt {
		return nil, fmt.Errorf("orm: UpsertMany of TenantUser sets the fields an update sets, not deletedAt")
	}
	if update.DeletedBy {
		return nil, fmt.Errorf("orm: UpsertMany of TenantUser sets the fields an update sets, not deletedBy")
	}
	if update.Version {
		return nil, fmt.Errorf("orm: UpsertMany of TenantUser sets the fields an update sets, not _version")
	}
	batch, err := upsertBatch("TenantUser", opts.Batch, 13106)
	if err != nil {
		return nil, err
	}
	if len(inputs) == 0 {
		return []UpsertResult[*types.TenantUser]{}, nil
	}
	if len(inputs) <= batch && !opts.OnlyIfChanged {
		return r.upsertBatches(ctx, inputs, on, update, batch, false)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]UpsertResult[*types.TenantUser], error) {
		return (&TenantUserRepository{tx: tx, txDB: r.database()}).upsertBatches(ctx, inputs, on, update, batch, opts.OnlyIfChanged)
	})
}

// upsertBatches is UpsertMany on the repository's connection, a batch at a
// time: each batch's statement, a read of the rows it left as they were,
// only if changed, and the second statement of each encrypted field.
func (r *TenantUserRepository) upsertBatches(ctx context.Context, inputs []*types.TenantUser, on TenantUserUniqueKey, update TenantUserFields, batch int, onlyIfChanged bool) ([]UpsertResult[*types.TenantUser], error) {
	key := tenantUserUniqueKeys[on]

	// Set audit fields

	// Each field update names takes the value the input would have
	// inserted, which an upsert only if changed compares with the row's.
	var setClauses, compareCurrent, compareNext []string
	if update.DisplayName {
		setClauses = append(setClauses, `display_name = EXCLUDED.display_name`)
		compareCurrent = append(compareCurrent, `tenant_user.display_name`)
		compareNext = append(compareNext, `EXCLUDED.display_name`)
	}
	if update.Tenant {
		setClauses = append(setClauses, `tenant_id = EXCLUDED.tenant_id`)
		compareCurrent = append(compareCurrent, `tenant_user.tenant_id`)
		compareNext = append(compareNext, `EXCLUDED.tenant_id`)
	}

	results := make([]UpsertResult[*types.TenantUser], 0, len(inputs))
	for start := 0; start < len(inputs); start += batch {
		chunk := inputs[start:min(start+batch, len(inputs))]
		prepared := chunk

		// The batch's rows, as CreateMany writes them.
		rows := make([][]batchInsertCell, 0, len(prepared))
		for _, input := range prepared {
			var row []batchInsertCell
			// Primary key: id. Schema-owned identities may supply a stable
			// UUID, matching CreateOne; a row without one takes the generated default.
			{
				cell := batchInsertCell{column: `id`}
				var zeroPrimaryKey types.IdentityUUID
				if primaryKey, ok := tenantUserUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
					cell.value, cell.set = primaryKey.ToUUID(), true
				}
				row = append(row, cell)
			}
			// Optional field: displayName
			{
				cell := batchInsertCell{column: `display_name`}
				if !reflect.ValueOf(input.DisplayName).IsZero() {
					cell.value = input.DisplayName
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: deletedAt
			{
				cell := batchInsertCell{column: `deleted_at`}
				if input.DeletedAt != nil {
					cell.value = time.Time(*input.DeletedAt)
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: deletedBy
			{
				cell := batchInsertCell{column: `deleted_by`}
				if input.DeletedBy != nil {
					cell.value = input.DeletedBy.ToUUID()
					cell.set = true
				}
				row = append(row, cell)
			}

			// Relationship foreign key columns, matching CreateOne
			// Relationship: tenant (FK: tenant_id)
			{
				cell := batchInsertCell{column: `tenant_id`}
				var zeroId types.IdentityUUID
				if relID, ok := tenantUserUUIDValue(input.Tenant.Id); ok && relID != zeroId {
					cell.value, cell.set = relID.ToUUID(), true
				}
				row = append(row, cell)
			}
			rows = append(rows, row)
		}
		fieldNames, valuePlaceholders, values := buildBatchInsert(rows)
		assignments := append([]string(nil), setClauses...)
		if len(setClauses) == 0 {
			// An update that names no field leaves each row as it is.
			assignments = append(assignments, key.keep)
		} else {
			values = append(values, time.Now())
			assignments = append(assignments, fmt.Sprintf("updated_at = $%d", len(values)))
		}
		query := fmt.Sprintf(
			`INSERT INTO tenant_user (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "created_at", "updated_at", "id", "tenant_id", "display_name", "deleted_at", "deleted_by", "_version", (xmax = 0) AS _inserted`,
			strings.Join(fieldNames, ", "),
			strings.Join(valuePlaceholders, ", "),
			key.conflict,
			strings.Join(assignments, ", "),
			upsertWhere(`tenant_user.deleted_at IS NULL`, compareCurrent, compareNext, onlyIfChanged),
		)
		returned, inserted, err := r.upsertReturned(ctx, query, values)
		if err != nil {
			return nil, err
		}

		// A row is its input's by the key's values; an input that sets none
		// of them, whose key the database generates, takes the next row whose
		// key no input holds, as the rows come back in the inputs' order.
		keys := make([]string, len(prepared))
		set := make([]bool, len(prepared))
		for i, input := range prepared {
			keys[i], set[i] = tenantUserKeyOf(on, input)
		}
		matcher := newUpsertMatcher(keys, set)
		matched := make([]*UpsertResult[*types.TenantUser], len(prepared))
		for n, row := range returned {
			text, ok := tenantUserKeyOf(on, row)
			i := matcher.take(text, ok)
			if i < 0 {
				return nil, fmt.Errorf("orm: UpsertMany of TenantUser wrote a row whose %s no input holds", string(on))
			}
			status := UpsertUnchanged
			if inserted[n] {
				status = UpsertInserted
			} else if len(setClauses) > 0 {
				status = UpsertUpdated
			}
			matched[i] = &UpsertResult[*types.TenantUser]{Row: row, Status: status}
		}

		// A row it did not return is one it left as it was, only if changed,
		// which it reads back by its key, or a deleted one.
		var left []int
		for i := range matched {
			if matched[i] == nil {
				left = append(left, i)
			}
		}
		if len(left) > 0 {
			if !onlyIfChanged {
				return nil, fmt.Errorf("the TenantUser row that holds the %s of input %d is deleted: %w", string(on), start+left[0], ErrNotFound)
			}
			keyValues := make([][]any, len(left))
			wanted := make([]*types.TenantUser, len(left))
			for n, i := range left {
				cells, ok := upsertCellValues(rows[i], key.columns)
				if !ok {
					return nil, fmt.Errorf("no TenantUser row holds an unset %s: %w", string(on), ErrNotFound)
				}
				keyValues[n], wanted[n] = cells, prepared[i]
			}
			found, err := r.rowsOfKeys(ctx, on, keyValues, wanted)
			if err != nil {
				return nil, err
			}
			for n, i := range left {
				matched[i] = &UpsertResult[*types.TenantUser]{Row: found[n], Status: UpsertUnchanged}
			}
		}
		for _, result := range matched {
			results = append(results, *result)
		}
	}
	return results, nil
}

// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *TenantUserRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.TenantUser, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.TenantUser
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert only if changed left as they were
// (D89). A key no live row holds is ErrNotFound.
func (r *TenantUserRepository) rowsOfKeys(ctx context.Context, on TenantUserUniqueKey, keys [][]any, inputs []*types.TenantUser) ([]*types.TenantUser, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(tenantUserUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.TenantUser{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := tenantUserKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.TenantUser, len(inputs))
	for i, input := range inputs {
		text, _ := tenantUserKeyOf(on, input)
		row := found[text]
		if row == nil || upsertHolds(row.DeletedAt) {
			return nil, fmt.Errorf("the TenantUser row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

// CreateMany inserts multiple TenantUser records in a single statement
func (r *TenantUserRepository) CreateMany(ctx context.Context, inputs []*types.TenantUser) ([]*types.TenantUser, error) {
	if len(inputs) == 0 {
		return []*types.TenantUser{}, nil
	}

	// Set audit fields

	// Build the batch INSERT in one pass over the fields. Each row records every
	// candidate column in the same order, with the value it binds or no value
	// when it leaves an optional column unset; buildBatchInsert inserts the
	// columns any row sets and writes DEFAULT for a row that leaves one unset.
	batch := make([][]batchInsertCell, 0, len(inputs))
	for _, input := range inputs {
		var row []batchInsertCell
		// Primary key: id. Schema-owned identities may supply a stable
		// UUID, matching CreateOne; a row without one takes the generated default.
		{
			cell := batchInsertCell{column: `id`}
			var zeroPrimaryKey types.IdentityUUID
			if primaryKey, ok := tenantUserUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
				cell.value, cell.set = primaryKey.ToUUID(), true
			}
			row = append(row, cell)
		}
		// Optional field: displayName
		{
			cell := batchInsertCell{column: `display_name`}
			if !reflect.ValueOf(input.DisplayName).IsZero() {
				cell.value = input.DisplayName
				cell.set = true
			}
			row = append(row, cell)
		}
		// Optional field: deletedAt
		{
			cell := batchInsertCell{column: `deleted_at`}
			if input.DeletedAt != nil {
				cell.value = time.Time(*input.DeletedAt)
				cell.set = true
			}
			row = append(row, cell)
		}
		// Optional field: deletedBy
		{
			cell := batchInsertCell{column: `deleted_by`}
			if input.DeletedBy != nil {
				cell.value = input.DeletedBy.ToUUID()
				cell.set = true
			}
			row = append(row, cell)
		}

		// Relationship foreign key columns, matching CreateOne
		// Relationship: tenant (FK: tenant_id)
		{
			cell := batchInsertCell{column: `tenant_id`}
			var zeroId types.IdentityUUID
			if relID, ok := tenantUserUUIDValue(input.Tenant.Id); ok && relID != zeroId {
				cell.value, cell.set = relID.ToUUID(), true
			}
			row = append(row, cell)
		}
		batch = append(batch, row)
	}
	fieldNames, valuePlaceholders, values := buildBatchInsert(batch)

	// Build RETURNING clause with explicit column order matching scan order (using OrderedMembers for schema order)
	returningClauseMany := `"created_at", "updated_at", "id", "tenant_id", "display_name", "deleted_at", "deleted_by", "_version"`
	query := fmt.Sprintf(
		`INSERT INTO tenant_user (%s) VALUES %s RETURNING %s`,
		strings.Join(fieldNames, ", "),
		strings.Join(valuePlaceholders, ", "),
		returningClauseMany,
	)

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute batch insert: %w", err)
	}
	defer rows.Close()

	// Scan results
	results := []*types.TenantUser{}
	for rows.Next() {
		result := &types.TenantUser{}
		// Create temporary variables for nullable fields that need pointer scanning

		var tempDisplayName sql.NullString

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)
		var tempRelTenant *types.IdentityUUID

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&result.CreatedAt,

			&result.UpdatedAt,

			&result.Id,

			&tempRelTenant,

			&tempDisplayName,

			&result.DeletedAt,

			&result.DeletedBy,

			&result.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}

		// Copy nullable fields when present

		if tempDisplayName.Valid {
			result.DisplayName = tempDisplayName.String
		}

		// Set relationship IDs from scanned FK values
		if tempRelTenant != nil {
			result.Tenant.Id = tenantUserUUIDPtr(*tempRelTenant)
		}
		results = append(results, result)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}

	return results, nil
}

// UpdateOne updates a single TenantUser record by ID
func (r *TenantUserRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *TenantUserUpdate) (*types.TenantUser, error) {
	return r.updateOne(ctx, id, update, nil)
}

// UpdateOneIfVersion updates a single TenantUser only if its current _version matches expectedVersion.
// It returns ErrVersionConflict when the row exists at another version and
// ErrNotFound when it does not exist.
func (r *TenantUserRepository) UpdateOneIfVersion(ctx context.Context, id types.IdentityUUID, expectedVersion int64, update *TenantUserUpdate) (*types.TenantUser, error) {
	return r.updateOne(ctx, id, update, &expectedVersion)
}

// versionMiss tells apart why a write fenced on _version matched no row:
// ErrVersionConflict when the row exists at another version, ErrNotFound when
// it does not exist or is soft-deleted.
func (r *TenantUserRepository) versionMiss(ctx context.Context, id types.IdentityUUID) error {
	query := `SELECT _version FROM tenant_user WHERE id = $1 AND deleted_at IS NULL`

	var version int64
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, id.ToUUID())
	} else {
		row = r.db.pool.QueryRow(ctx, query, id.ToUUID())
	}
	if err := row.Scan(&version); err != nil {
		if err == pgx.ErrNoRows {
			return ErrNotFound
		}
		return fmt.Errorf("failed to read TenantUser version: %w", err)
	}
	return ErrVersionConflict
}

func (r *TenantUserRepository) updateOne(ctx context.Context, id types.IdentityUUID, update *TenantUserUpdate, expectedVersion *int64) (*types.TenantUser, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.DisplayName != nil && update.DisplayNameSetNull {
		return nil, fmt.Errorf("display_name cannot be updated with both value and null assignment")
	}
	if update.DisplayNameSetNull {
		setClauses = append(setClauses, `display_name = NULL`)
	} else if update.DisplayName != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`display_name = $%d`, paramNum))
		values = append(values, *update.DisplayName)
	}
	// Handle relationship foreign key: tenant
	if update.TenantID != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf("tenant_id = $%d", paramNum))
		values = append(values, update.TenantID.ToUUID())
	}

	// Set updated_at
	paramNum++
	setClauses = append(setClauses, fmt.Sprintf("updated_at = $%d", paramNum))
	values = append(values, time.Now())

	// Set updated_by

	if len(setClauses) == 0 {
		return nil, fmt.Errorf("no fields to update")
	}

	paramNum++
	values = append(values, id.ToUUID())

	query := fmt.Sprintf(
		`UPDATE tenant_user SET %s WHERE id = $%d`,
		strings.Join(setClauses, ", "),
		paramNum,
	)
	if expectedVersion != nil {
		paramNum++
		values = append(values, *expectedVersion)
		query += fmt.Sprintf(" AND _version = $%d", paramNum)
	}
	query += " AND deleted_at IS NULL"

	// Build RETURNING clause with explicit column order matching scan order (using OrderedMembers for schema order)
	query += ` RETURNING "created_at", "updated_at", "id", "tenant_id", "display_name", "deleted_at", "deleted_by", "_version"`

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}

	// Scan result
	result := &types.TenantUser{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempDisplayName sql.NullString

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)
	var tempRelTenant *types.IdentityUUID

	// Scan all fields in schema order (matches DDL column order)
	if err := row.Scan(

		&result.CreatedAt,

		&result.UpdatedAt,

		&result.Id,

		&tempRelTenant,

		&tempDisplayName,

		&result.DeletedAt,

		&result.DeletedBy,

		&result.Version,
	); err != nil {
		if err == pgx.ErrNoRows {
			if expectedVersion != nil {
				return nil, r.versionMiss(ctx, id)
			}
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("failed to scan result: %w", err)
	}

	// Copy nullable fields when present

	if tempDisplayName.Valid {
		result.DisplayName = tempDisplayName.String
	}

	// Set relationship IDs from scanned FK values
	if tempRelTenant != nil {
		result.Tenant.Id = tenantUserUUIDPtr(*tempRelTenant)
	}

	return result, nil
}

// UpdateMany updates multiple TenantUser records matching the filter
func (r *TenantUserRepository) UpdateMany(ctx context.Context, filter *TenantUserFilter, update *TenantUserUpdate) (int, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.DisplayName != nil && update.DisplayNameSetNull {
		return 0, fmt.Errorf("display_name cannot be updated with both value and null assignment")
	}
	if update.DisplayNameSetNull {
		setClauses = append(setClauses, `display_name = NULL`)
	} else if update.DisplayName != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`display_name = $%d`, paramNum))
		values = append(values, *update.DisplayName)
	}
	// Handle relationship foreign key: tenant
	if update.TenantID != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf("tenant_id = $%d", paramNum))
		values = append(values, update.TenantID.ToUUID())
	}

	// Set updated_at
	paramNum++
	setClauses = append(setClauses, fmt.Sprintf("updated_at = $%d", paramNum))
	values = append(values, time.Now())

	// Set updated_by

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)
	if whereClause == "" {
		whereClause = " WHERE deleted_at IS NULL"
	} else {
		whereClause += " AND deleted_at IS NULL"
	}

	query := fmt.Sprintf(
		`UPDATE tenant_user SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne soft deletes a single TenantUser record by ID
func (r *TenantUserRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	if !HasUserID(ctx) {
		return ErrNoUserInContext
	}
	query := `UPDATE tenant_user SET deleted_at = $1, deleted_by = $2 WHERE id = $3 AND deleted_at IS NULL`
	queryArgs := []interface{}{time.Now(), GetUserID(ctx), id.ToUUID()}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}

// DeleteOneIfVersion soft deletes a single TenantUser only if its current
// _version matches expectedVersion. It returns ErrVersionConflict when the row
// exists at another version and ErrNotFound when it does not exist.
func (r *TenantUserRepository) DeleteOneIfVersion(ctx context.Context, id types.IdentityUUID, expectedVersion int64) error {
	if !HasUserID(ctx) {
		return ErrNoUserInContext
	}
	query := `UPDATE tenant_user SET deleted_at = $1, deleted_by = $2 WHERE id = $3 AND _version = $4 AND deleted_at IS NULL`
	queryArgs := []interface{}{time.Now(), GetUserID(ctx), id.ToUUID(), expectedVersion}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return r.versionMiss(ctx, id)
	}

	return nil
}

// DeleteMany soft deletes multiple TenantUser records matching the filter
func (r *TenantUserRepository) DeleteMany(ctx context.Context, filter *TenantUserFilter) (int, error) {
	if !HasUserID(ctx) {
		return 0, ErrNoUserInContext
	}

	// Build WHERE clause
	values := []interface{}{time.Now(), GetUserID(ctx)}
	whereClause := filter.buildWhereClause(&values, 2)

	if whereClause == "" {
		whereClause = " WHERE deleted_at IS NULL"
	} else {
		whereClause += " AND deleted_at IS NULL"
	}
	query := fmt.Sprintf(`UPDATE tenant_user SET deleted_at = $1, deleted_by = $2%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// HardDeleteOne permanently deletes a single TenantUser record by ID.
// The history tombstone records the context user as its deleted_by.
func (r *TenantUserRepository) HardDeleteOne(ctx context.Context, id types.IdentityUUID) error {
	query := historyActorCTE + `DELETE FROM tenant_user USING history_actor WHERE id = $2`
	queryArgs := []interface{}{historyActor(ctx), id.ToUUID()}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
		if err == nil {
			err = clearHistoryActor(ctx, r.tx)
		}
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}
